import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

template <int THREADS>
__global__ void l2norm_kernel(const __half* __restrict__ input,
                              __half* __restrict__ output,
                              int dim) {
    int row = blockIdx.x;
    int tid = threadIdx.x;

    const __half* in_row = input + (size_t)row * dim;
    __half* out_row = output + (size_t)row * dim;

    // ---- compute sum of squares ----
    float sum = 0.0f;
    for (int i = tid; i < dim; i += THREADS) {
        __half v = in_row[i];
        float f = __half2float(v);
        sum += f * f;
    }

    // ---- reduction in shared memory ----
    __shared__ float shmem[THREADS];
    shmem[tid] = sum;
    __syncthreads();

    #pragma unroll
    for (int stride = THREADS / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shmem[tid] += shmem[tid + stride];
        }
        __syncthreads();
    }

    // ---- compute norm (add epsilon to avoid div‑by‑zero) ----
    float norm = sqrtf(shmem[0]) + 1e-6f;

    // ---- write normalized values ----
    for (int i = tid; i < dim; i += THREADS) {
        __half v = in_row[i];
        float f = __half2float(v);
        float n = f / norm;
        out_row[i] = __float2half(n);
    }
}

// wrapper
torch::Tensor l2norm_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");

    auto batch = input.size(0);
    auto dim   = input.size(1);
    auto options = torch::TensorOptions()
                       .dtype(torch::kHalf)
                       .device(input.device());

    torch::Tensor output = torch::empty({batch, dim}, options);

    const int threads = 256;
    const dim3 blocks(batch);
    const dim3 threads_per_block(threads);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        input.scalar_type(), "l2norm_cuda", ([&] {
            l2norm_kernel<threads><<<blocks, threads_per_block, 0,
                                     at::cuda::getCurrentCUDAStream()>>>(
                reinterpret_cast<const __half*>(input.data_ptr()),
                reinterpret_cast<__half*>(output.data_ptr()),
                dim);
        }));
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel launch error: ") +
                                 cudaGetErrorString(err));
    }
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("l2norm_cuda", &l2norm_cuda, "L2Norm CUDA (fp16)");
}
'''

# compile the extension
l2norm_ext = load_inline(name='l2norm_ext',
                         cpp_sources='',
                         cuda_sources=src,
                         functions=['l2norm_cuda'],
                         verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    Performs L2‑normalization along dimension 1 on fp16 tensors.
    """
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure fp16 and CUDA
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        if not x.is_cuda:
            x = x.cuda()
        # keep shape, rely on kernel to produce same shape and dtype
        return l2norm_ext.l2norm_cuda(x)

# Example usage (mirrors reference get_inputs)
if __name__ == "__main__":
    batch_size = 32768
    dim = 65535
    x = torch.rand(batch_size, dim, dtype=torch.float16, device='cuda')
    model = ModelNew()
    y = model(x)
    # sanity check (compare with PyTorch implementation on a small slice)
    with torch.no_grad():
        ref = x / torch.norm(x, p=2, dim=1, keepdim=True)
        print(torch.allclose(y[:10], ref[:10], atol=1e-3, rtol=1e-3))
